export type SpaceType =
  | 'town'
  | 'empty'
  | 'blue'
  | 'red'
  | 'shop_item'
  | 'shop_weapon'
  | 'shop_magic'
  | 'church'
  | 'dark_gate'
  | 'vault'
  | 'boss'
  | 'tavern'
  | 'guild'
  | 'fishing'
  | 'isekai_event'
  | 'mystery_chest'
  | 'home';

export type BiomeType =
  | 'grass'
  | 'forest'
  | 'waterfall_forest'
  | 'snow'
  | 'desert'
  | 'volcano'
  | 'cavern'
  | 'coral'
  | 'abyss'
  | 'castle'
  | 'fairy_grove'
  | 'crystal_cavern'
  | 'celestial'
  | 'steampunk'
  | 'sakura_shrine';

export type RealmId = 'solaria' | 'frostpeak' | 'sunfire' | 'abyss' | 'celestial' | 'emerald';

export interface TownData {
  project?: 'market' | 'sanctuary' | 'watchtower';
  name: string;
  level: number;
  baseValue: number;
  taxYield: number;
  ownerId: number | null;
  isOccupiedByMonster: boolean;
  monsterName: string;
  monsterHp: number;
  monsterMaxHp?: number;
  monsterAtk: number;
  monsterDef: number;
  specialization?: 'trade_port' | 'fortress' | 'mining' | null;
}

export interface HomeData {
  ownerId: number;
  ownerName: string;
  level: number;
  purchasePrice?: number;
  visitorsCount?: number;
  tollFee?: number;
}

export interface BoardNode {
  id: number;
  gx: number;
  gy: number;
  gz: number;
  type: SpaceType;
  name: string;
  biome: BiomeType;
  neighbors: number[];
  townData?: TownData;
  homeData?: HomeData;
  realmId: RealmId;
  realmName: string;
  subRegionName: string;
  weather: 'sunny' | 'rain' | 'snow' | 'heatwave' | 'miasma';
  isGrandBridge?: boolean;
  regionKey?: string;
  routeKind?: 'bridge' | 'skyway' | 'tunnel' | 'causeway';
}

